const c06e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function c06api(path,opts={}){const r=await fetch(path,{headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts});const ct=r.headers.get('content-type')||'';const b=ct.includes('json')?await r.json():await r.text();if(!r.ok)throw new Error(b?.detail||b?.error?.code||String(b));return b}
const c06old=window.operationsLearningTab;
window.operationsLearningTab=async(el,p)=>{await c06old(el,p);try{const d=await c06api(`/api/v1/projects/${p.project_id}/recruitment-intelligence`);window.__c06Intel=d;const chans=d.channels||[];const sig=d.market?.signals||[];el.insertAdjacentHTML('beforeend',`<section class="panel" style="margin-top:12px"><div class="panel-head"><div><h3>Recruitment Intelligence / 渠道效能</h3><span class="subtle">渠道效能只用于招聘资源规划，不是候选人排序；未人工确认的数据只作 advisory。</span></div><button class="btn small primary" onclick="c06AddObservation()">录入渠道观测</button></div><div class="panel-body">${chans.length?`<div class="table-wrap"><table class="table"><thead><tr><th>渠道</th><th>样本</th><th>联系率</th><th>面试率</th><th>Offer率</th><th>录用/来源</th><th>每录用成本</th><th>确认</th></tr></thead><tbody>${chans.map(x=>`<tr><td><strong>${c06e(x.channel)}</strong></td><td>${x.sourced} → ${x.hired}</td><td>${x.contact_rate==null?'—':Math.round(x.contact_rate*100)+'%'}</td><td>${x.interview_rate==null?'—':Math.round(x.interview_rate*100)+'%'}</td><td>${x.offer_rate==null?'—':Math.round(x.offer_rate*100)+'%'}</td><td>${x.hire_rate_from_sourced==null?'—':Math.round(x.hire_rate_from_sourced*100)+'%'}</td><td>${x.cost_per_hire_cny==null?'—':'¥'+x.cost_per_hire_cny}</td><td><span class="status ${x.all_human_confirmed?'good':'warn'}">${x.all_human_confirmed?'human-confirmed':'advisory'}</span></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">尚无渠道效果观测。计划中的渠道不会因为被填写就自动获得“有效”结论。</div>'}${d.measurement_gaps?.length?`<div class="divider"></div><div class="status warn" style="display:block">缺少测量的计划渠道：${d.measurement_gaps.map(c06e).join('、')}</div>`:''}<div class="divider"></div><h4>市场参考</h4><div class="subtle">${c06e(d.market?.guardrail||'')}</div>${sig.length?`<div class="quick-list" style="margin-top:8px">${sig.slice(0,8).map(x=>`<div class="quick-item"><div><strong>${c06e(x.title||x.occupation_group||x.industry||x.kind)}</strong><div class="quick-note">${c06e(x.shortage_level||x.geography||x.period||'')} ${x.salary_median_10k!=null?'· 年薪中位数参考 '+x.salary_median_10k+' 万':''}</div></div></div>`).join('')}</div>`:'<div class="empty">当前岗位/地点未命中足够精确的市场参考；系统不会用宽口径数据伪造精确结论。</div>'}</div></section>`);await c06KnowledgePanel(el,p)}catch(e){console.warn('convergence06 intelligence unavailable',e)}};
window.c06AddObservation=()=>{c05modal('录入渠道效果观测',`<div class="form-grid"><div class="field"><label>渠道</label><input id="c06-ch" class="input"></div><div class="field"><label>期间</label><input id="c06-period" class="input" placeholder="2026Q4"></div>${['sourced','contacted','screened','interviewed','offered','hired'].map(k=>`<div class="field"><label>${k}</label><input id="c06-${k}" class="input" type="number" min="0" value="0"></div>`).join('')}<div class="field"><label>成本 CNY</label><input id="c06-spend" class="input" type="number" min="0" value="0"></div><div class="field"><label>数据来源</label><input id="c06-prov" class="input" value="manual"></div><div class="field full"><label><input id="c06-confirmed" type="checkbox"> 我已人工确认这组漏斗数据</label></div><div class="field full"><label>说明</label><textarea id="c06-notes" class="textarea"></textarea></div></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="c06SaveObservation()">保存</button>`)};
window.c06SaveObservation=async()=>{try{const n=k=>Number(document.querySelector('#c06-'+k).value||0);await c06api(`/api/v1/projects/${window.__c05ProjectId}/sourcing-observations`,{method:'POST',body:JSON.stringify({channel:document.querySelector('#c06-ch').value,period:document.querySelector('#c06-period').value,sourced:n('sourced'),contacted:n('contacted'),screened:n('screened'),interviewed:n('interviewed'),offered:n('offered'),hired:n('hired'),spend_cny:n('spend'),human_confirmed:document.querySelector('#c06-confirmed').checked,provenance:document.querySelector('#c06-prov').value,notes:document.querySelector('#c06-notes').value})});closeModal();c05toast('渠道观测已保存');c05Reload()}catch(e){c05toast(e.message,true)}};
async function c06KnowledgePanel(el,p){const pk=await c06api('/api/v1/knowledge-packages');const cur=window.__c05Data?.curation||[];const applicable=cur.filter(x=>['reviewed','exported'].includes(x.status)&&['confirm_alias','confirm_specialization','confirm_competency_alias'].includes(x.proposed_action));el.insertAdjacentHTML('beforeend',`<section class="panel" style="margin-top:12px"><div class="panel-head"><div><h3>Controlled Knowledge Apply</h3><span class="subtle">恢复 0.8.x 的“暂存 → 完整性检查 → 语义差异 → 显式摘要确认 → 激活 → 可回滚”边界。</span></div><button class="btn small" onclick="c06RollbackKnowledge()">回滚最近一次激活</button></div><div class="panel-body">${applicable.length?`<div class="quick-list">${applicable.map(x=>`<div class="quick-item"><div><strong>${c06e(x.title)}</strong><div class="quick-note">${c06e(x.proposed_action)} · proposal ${c06e(x.id.slice(0,8))}</div></div><button class="btn small primary" onclick="c06PrepareApply('${x.id}','${c06e(x.proposed_action)}')">准备受控 Apply</button></div>`).join('')}</div>`:'<div class="empty">当前没有可直接 Apply 的已审核职位/能力别名治理项。CREATE_CANONICAL 等高风险动作仍保持 export-only。</div>'}<div class="divider"></div><h4>已暂存知识包</h4>${pk.packages?.length?`<div class="quick-list">${pk.packages.map(x=>`<div class="quick-item"><div><strong>${c06e(x.package_id)}</strong><div class="quick-note">${c06e(x.status)} · +${x.semantic_diff?.totals?.added||0} / ~${x.semantic_diff?.totals?.changed||0} / -${x.semantic_diff?.totals?.removed||0}</div></div>${['prepared','rolled_back'].includes(x.status)?`<button class="btn small danger" onclick="c06ActivateKnowledge('${x.package_id}','${x.activation_requires_explicit_digest}')">按摘要激活</button>`:''}</div>`).join('')}</div>`:'<div class="empty">暂无暂存知识包。</div>'}</div></section>`)}
window.c06PrepareApply=(id,action)=>{const isComp=action==='confirm_competency_alias';const title=prompt(isComp?'需要加入 competency 的能力别名：':'需要加入 taxonomy 的市场/别名标题：','');if(!title)return;const target=prompt(isComp?'目标 competency_id：':'目标 role_id / specialization_id：','');if(!target)return;const targetType=isComp?'competency':(action==='confirm_specialization'?'specialization':(prompt('目标类型 role / specialization：','role')||'role'));c06api(`/api/v1/knowledge-curation/${id}/prepare-apply`,{method:'POST',body:JSON.stringify({source_title:title,target_id:target,target_type:targetType,actor:'human'})}).then(r=>{c05toast(`知识包已暂存；语义新增 ${r.semantic_diff.totals.added} 项，Active DB 尚未修改`);c05Reload()}).catch(e=>c05toast(e.message,true))};
window.c06ActivateKnowledge=async(id,digest)=>{if(!confirm(`确认按已显示的语义差异激活 ${id}？该操作会修改 active Knowledge，但保留可回滚备份。`))return;try{const r=await c06api(`/api/v1/knowledge-packages/${id}/activate`,{method:'POST',body:JSON.stringify({expected_digest:digest,actor:'human'})});c05toast(`已激活 ${r.source_type}；可回滚`);c05Reload()}catch(e){c05toast(e.message,true)}};
window.c06RollbackKnowledge=async()=>{if(!confirm('回滚最近一次 Knowledge 激活？'))return;try{const r=await c06api('/api/v1/knowledge-packages/rollback',{method:'POST',body:JSON.stringify({actor:'human'})});c05toast(`已回滚 ${r.package_id}`);c05Reload()}catch(e){c05toast(e.message,true)}};
